const input = $input.first().json;
const body = input.body || input;
const caseId = Number(body.case_id);
const agentRaw = String(body.agent || body.ra_code || '').toUpperCase().replace('_', '-');
if (!Number.isInteger(caseId) || caseId <= 0) throw new Error('case_id must be a positive numeric car_cases.case_id');
if (!/^RA-0[1-6]$/.test(agentRaw)) throw new Error('agent/ra_code must be RA-01 through RA-06');
const signalMap = {'RA-01':'ra01_ready','RA-02':'ra02_ready','RA-03':'ra03_ready','RA-04':'ra04_ready','RA-05':'ra05_ready','RA-06':'ra06_ready'};
const reportJson = typeof body.report_json === 'string' ? JSON.parse(body.report_json || '{}') : (body.report_json || {});
return [{ json: {
  case_id: caseId,
  agent: agentRaw,
  signal_type: body.signal_type || signalMap[agentRaw],
  status: body.status || 'complete',
  report: body.report || body.report_markdown || body.summary || null,
  report_url: body.report_url || body.report_md_path || body.evidence_url || null,
  report_json_path: body.report_json_path || null,
  report_json: reportJson,
  completed_by: body.completed_by || body.submitted_by || 'RA Completion Receiver',
  notes: body.notes || null
}}];
